import React from 'react'
import { connect } from 'react-redux'
import { Modal, Spin, Radio, Collapse, Button, Icon } from 'antd'
import { injectIntl } from 'react-intl'
import GolifePassengerActions from '../../redux/golifePassenger/actions'
import IntlMessages from '../../components/utility/intlMessages'
import ModalStyle from './modal.style'

const RadioGroup = Radio.Group
const Panel = Collapse.Panel
const { resetStateGolifePassenger, createClaimGocarPassenger } = GolifePassengerActions

class Benefits extends React.PureComponent {
  state = {
    value: '',
    btnLoading: false,
    claimType: '',
    displaySafeScreen: false
  }
  handleCancelShowBenefits = () => {
    this.setState({ value: '' })
    this.props.isClose()
  }
  onChange = (e) => {
    this.setState({ value: e.target.value })
  }
  genExtra = () => (
    <Icon type='down' />
  )
  isActive = status => {
    this.setState({ claimType: status })
  }
  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }
  createClaim = () => {
    this.props.resetStateGolifePassenger()
    this.setState({ btnLoading: true })
    const { profile } = this.props
    let source = window.sessionStorage.getItem('utm_source')
    if (!source) {
      source = 'direct'
    }
    if (this.state.claimType) {
      const payload = {
        order_id: profile.orderId,
        user_id: profile.user_id,
        benefit_id: this.state.value,
        source: source
      }
      this.props.createClaimGocarPassenger(payload)
    } else {
      this.setState({ displaySafeScreen: true })
    }
    setTimeout(() => {
      this.setState({ btnLoading: false })
    }, 2000)
  }
  render () {
    const { isOpen, benefits } = this.props
    return (
      <Modal
        title={
          <ModalStyle>
            <div className='modal-text'>
              {this.intlText({ id: 'Pilih manfaat untuk klaim' })}
            </div>
          </ModalStyle>
        }
        visible={isOpen}
        footer={null}
        onCancel={this.handleCancelShowBenefits}
        wrapClassName='benefits-modal'
        maskClosable={false}
      >
        <Spin spinning={benefits === undefined} tip='Loading...'>
          {
            this.state.displaySafeScreen ? this.noBenefitInfo() : (
              (benefits !== undefined && benefits.length > 0) && (
                <RadioGroup
                  onChange={this.onChange}
                  value={this.state.value}
                  className='benefits-radio'
                >
                  {
                    benefits.map((val, index) => {
                      if (val.benefits.length > 1) {
                        return (
                          <Collapse key={index}>
                            <Panel
                              header={
                                <div className='benefits-collapse-header'>
                                  <b><IntlMessages id={val.benefit_group_name} /></b>
                                  <br />
                                  <span><IntlMessages id={val.benefit_group_description} /></span>
                                </div>
                              }
                              key={index}
                              extra={this.genExtra()}
                            >
                              {
                                val.benefits.map((value, i) => {
                                  return (
                                    <Radio
                                      key={i}
                                      value={value.benefit_id}
                                      onChange={() => this.isActive(value.is_claim_active)}
                                    >
                                      <b><IntlMessages id={value.benefit_name} /></b>
                                    </Radio>
                                  )
                                })
                              }
                            </Panel>
                          </Collapse>
                        )
                      } else {
                        return val.benefits.map((value, i) => {
                          return (
                            <div key={i} className='radio-content-wrapper'>
                              <Radio
                                key={i}
                                value={value.benefit_id}
                                onChange={() => this.isActive(value.is_claim_active)}
                              >
                                <b><IntlMessages id={value.benefit_name} /></b>
                                <br />
                                <span className='description'><IntlMessages id={value.description} /></span>
                              </Radio>
                              <br />
                            </div>
                          )
                        })
                      }
                    })
                  }

                  {
                    (benefits !== undefined && benefits.length < 1) && (
                      <h3><IntlMessages id='Manfaat tidak ditemukan' /></h3>
                    )
                  }
                  {
                    (benefits !== undefined && benefits.length > 0) && (
                      <div className='next-btn-container'>
                        <Button
                          type='primary'
                          disabled={this.state.value === ''}
                          onClick={this.createClaim}
                          loading={this.state.btnLoading}
                        ><IntlMessages id='Berikutnya' /></Button>
                      </div>
                    )
                  }
                </RadioGroup>
              )
            )
          }
        </Spin>

      </Modal>
    )
  }
}

export default connect(
  state => ({}),
  { createClaimGocarPassenger, resetStateGolifePassenger }
)(injectIntl(Benefits))
