import React from 'react'
import { connect } from 'react-redux'
import {
  Row,
  Col,
  Card,
  Form,
  Input,
  Button,
  Alert,
  Modal,
  Steps,
  notification,
  Checkbox,
  Select
} from 'antd'
import GolifeStyled from './golife.style'
import GolifeActions from '../../redux/golifePassenger/actions'
import authActions from '../../redux/auth/actions'
import GolifeMenu from '../../image/gojek-menu.png'
import Process from '../../image/process.png'
import Riwayat from '../../image/riyawat-golife.png'
import GorideStatus from '../../image/golife-status.png'
import NumericInput from './numericinput'
import IntlMessages from '../../components/utility/intlMessages'
import ReactDOM from 'react-dom'
import BenefitsModal from './new_benefits_ui'
import { isAndroid } from 'react-device-detect'
import { injectIntl } from 'react-intl'

const REACT_APP_ANDROID = process.env.REACT_APP_ANDROID
const FormItem = Form.Item
const Step = Steps.Step
const { resetStateGolifePassenger, getProfileDetails, createOrder, getBenefits } = GolifeActions
const { updateUser } = authActions
const { Option } = Select

class GolifePassenger extends React.Component {
  state = {
    profile: {},
    loading: false,
    benefitsModal: false,
    isGolife: window.sessionStorage.getItem('isFromGolife'),
    notifications: {},
    selectedOption: undefined,
    termsContentOpen: false,
    termsValue: false
  }

  componentWillReceiveProps (nextProps) {
    const { history } = this.props
    const { createOrderStatus } = nextProps.GolifePassenger
    const { dataClaim, createClaimGocarPassengerStatus } = nextProps
    const { isGolife } = this.state

    if (createClaimGocarPassengerStatus !== '' && createClaimGocarPassengerStatus === 'success') {
      window.onpopstate = e => {
        history.push('/go-life/claim')
      }
      if (REACT_APP_ANDROID && isAndroid && isGolife) {
        history.push(`/go-life/${dataClaim.claim_no}/success`)
      } else {
        history.push(`/go-life/claim-details/${dataClaim.claim_id}`)
      }
    }

    if (createClaimGocarPassengerStatus !== '' && createClaimGocarPassengerStatus !== 'success') {
      if (this.state.notifications.createClaimGocarPassengerStatus === undefined || this.state.notifications.createClaimGocarPassengerStatus !== true) {
        notification.error({
          message: this.intlText({ id: createClaimGocarPassengerStatus }),
          description: '',
          onClose: () => {
            this.setState({
              notifications: {
                ...this.state.notifications,
                createClaimGocarPassengerStatus: false
              }
            })
          }
        })
      }
      this.setState({
        notifications: {
          ...this.state.notifications,
          createClaimGocarPassengerStatus: true
        }
      })
      this.props.resetStateGolifePassenger()
    }

    if (createOrderStatus !== '' && createOrderStatus === 'success') {
      this.setState({ createOrderStatus, loading: false, benefitsModal: true })
      this.fetchBenefits()
    }

    if (createOrderStatus !== '' && createOrderStatus !== 'success') {
      this.setState({ createOrderStatus, loading: false })
    }
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  fetchBenefits = () => {
    const { dataUser } = this.props
    this.props.resetStateGolifePassenger()
    this.props.getBenefits({ orderId: this.state.profile.orderId, userId: dataUser.user_id })
  }

  componentDidMount () {
    const { dataUser } = this.props
    this.setState({ profile: dataUser })
  }

  async validateForm () {
    return new Promise(resolve => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  handleSubmit = async e => {
    e.preventDefault()
    if (this.state.termsValue) {
      this.setState({ loading: true })
      this.props.resetStateGolifePassenger()
      const valid = await this.validateForm()
      if (!valid) {
        return
      }
      const { form, dataUser } = this.props
      let data = form.getFieldsValue()
      window.sessionStorage.setItem('email', data.email)
      data = {
        ...data,
        user_id: dataUser.user_id,
        phone_number: dataUser.phone
      }
      this.props.createOrder(data)
      this.props.updateUser(data)
      ReactDOM.findDOMNode(this).scrollIntoView()
    } else {
      notification.error({
        message: this.intlText({ id: 'Anda harus membaca dan menyetujui pernyataan terlampir!' }),
        description: ''
      })
    }
  }

  onClose = () => {
    this.props.resetStateGolifePassenger()
    this.setState({ createOrderStatus: undefined })
  }

  onChangeOrderId = e => {
    this.setState({
      profile: {
        ...this.state.profile,
        orderId: e
      }
    })
  }

  onChangeEmail = e => {
    this.setState({
      profile: {
        ...this.state.profile,
        email: e.target.value
      }
    })
  }

  onChangeName = e => {
    this.setState({
      profile: {
        ...this.state.profile,
        name: e.target.value
      }
    })
  }

  showModal = () => {
    this.setState({ visible: true })
  }

  handleCancel = e => {
    this.setState({ visible: false })
  }

  goToClaimlist = () => {
    const { history } = this.props
    history.push('/?source=claim')
  }

  onCloseBenefitModal = () => {
    this.setState({ benefitsModal: false })
  }

  handleSelectChange = val => {
    this.setState({
      selectedOption: val
    })
  }

  openTermsContent = () => {
    this.setState({ termsContentOpen: true })
  }

  onTermsChange = e => {
    this.setState({
      termsValue: !this.state.termsValue
    })
  }

  handleTermsCancel = () => {
    this.setState({ termsContentOpen: false })
  }

  render () {
    const { getFieldDecorator } = this.props.form
    const { profile, createOrderStatus, selectedOption } = this.state
    // const { history } = this.props
    // if (createOrderStatus === 'success') {
    //   history.push(`/gojek-passenger/${profile.orderId}/benefits`)
    // }
    const checkOrderId = profile.orderId === undefined || profile.orderId === ''
    const checkEmail = profile.email === undefined || profile.email === ''
    const checkName = profile.name === undefined || profile.name === ''
    const optionSelected = selectedOption === undefined || selectedOption === ''
    // let stylePrevent = {}
    // if (this.state.visible) {
    //   stylePrevent = {
    //     display: 'none'
    //   }
    // }
    return (
      <div>
        <GolifeStyled>
          <Row style={{ display: 'flex', justifyContent: 'center' }}>
            <BenefitsModal
              isOpen={this.state.benefitsModal}
              benefits={this.props.dataBenefits ? this.props.dataBenefits : ''}
              isClose={this.onCloseBenefitModal}
              profile={profile}
            />
            <Modal title='' visible={this.state.visible} footer={null} closable onCancel={this.handleCancel}>
              <Steps progressDot direction='vertical' size='small' current={4}>
                <Step title={<IntlMessages id='Buka aplikasi GO-LIFE' />} />
                <Step
                  title={<IntlMessages id='Klik “Pesanan”' />}
                  description={<img src={GolifeMenu} style={{ width: '100%', height: 'auto' }} alt='' />}
                />
                <Step
                  title={<IntlMessages id='Klik “Riwayat” di bagian kanan atas aplikasi' />}
                  description={<img src={Process} style={{ width: '100%', height: 'auto' }} alt='' />}
                />
                <Step
                  title={<IntlMessages id='Pilih perjalanan yang akan diklaim' />}
                  description={<img src={Riwayat} style={{ width: '100%', height: 'auto' }} alt='' />}
                />
                <Step
                  title={<IntlMessages id='Order ID berada di bagian kanan atas aplikasi' />}
                  description={<img src={GorideStatus} style={{ width: '100%', height: 'auto' }} alt='' />}
                />
              </Steps>
            </Modal>
            <Modal title='' visible={this.state.termsContentOpen} footer={null} closable onCancel={this.handleTermsCancel}>
              <p style={{ marginTop: '20px' }}><IntlMessages id='Saya sebagai Customer GoLife menyatakan bahwa benar adanya mengalami kerugian dan/ kehilangan terhadap asset pribadi saya dan/ diri saya yang diakibatkan pengerjaan salah satu layanan GoLife' /></p>
              <p><IntlMessages id='Dengan ini saya menuntut ganti rugi ke GoLife atas kerugian yang saya alami tersebut di atas.' /></p>
              <p><IntlMessages id='Pernyataan ini dibuat secara elektronik oleh saya (Customer golife Indonesia) dalam keadaan sadar dan tanpa ada paksaan dari pihak manapun' /></p>
              <p><IntlMessages id='Dengan demikian saya mengisi form ini dan memberikan pernyataan dengan benar' /></p>
            </Modal>
            <Col>
              <h1
                style={{
                  fontSize: '18px',
                  fontWeight: '700',
                  textAlign: 'center',
                  marginBottom: '16px'
                }}
              >
                <IntlMessages id='Go Life Claim' />
              </h1>
              {createOrderStatus === 'success' ? (
                <Alert
                  message={<IntlMessages id='Klaim Anda telah terproses, tim kami akan segera menghubungi Anda melalui email.' />}
                  type='success'
                  closable
                  onClose={this.onClose}
                />
              ) : createOrderStatus !== '' && createOrderStatus !== undefined ? (
                <Alert message={<IntlMessages id={createOrderStatus} />} type='error' closable onClose={this.onClose} />
              ) : (
                ''
              )}
              <Card>
                <Form onSubmit={this.handleSubmit}>
                  <FormItem>
                    <Row gutter={8}>
                      <Col span={24}>
                        <FormItem>
                          {getFieldDecorator('email', {
                            initialValue: profile.email,
                            rules: [
                              {
                                type: 'email',
                                message: <IntlMessages id='Please input a valid email!' />
                              },
                              {
                                required: true,
                                message: <IntlMessages id='Please input your email!' />
                              }
                            ]
                          })(<Input
                            placeholder={this.intlText({ id: 'Email' })}
                            onChange={this.onChangeEmail}
                          />)}
                        </FormItem>
                      </Col>
                    </Row>
                  </FormItem>
                  <FormItem>
                    <Row gutter={8}>
                      <Col span={24}>
                        <FormItem>
                          {getFieldDecorator('name', {
                            initialValue: profile.name,
                            rules: [
                              {
                                required: true,
                                message: <IntlMessages id='Please input your name!' />
                              }
                            ]
                          })(<Input
                            placeholder={this.intlText({ id: 'Name' })}
                            onChange={this.onChangeName}
                          />)}
                        </FormItem>
                      </Col>
                    </Row>
                  </FormItem>
                  <FormItem>
                    <Row gutter={8}>
                      <Col span={24}>
                        <FormItem>
                          {getFieldDecorator('orderId', {
                            initialValue: profile.orderId,
                            rules: [
                              {
                                required: true,
                                message: <IntlMessages id='Please input your order ID!' />
                              }
                            ]
                          })(<NumericInput
                            placeholder={this.intlText({ id: 'Order ID' })}
                            onChange={this.onChangeOrderId}
                          />)}
                        </FormItem>
                      </Col>
                    </Row>
                  </FormItem>
                  <FormItem>
                    <Row gutter={8}>
                      <Col span={24}>
                        <FormItem>
                          {getFieldDecorator('claimType', {
                            rules: [
                              {
                                required: true,
                                message: <IntlMessages id='Please select your claim type!' />
                              }
                            ]
                          })(
                            <Select
                              placeholder={this.intlText({ id: 'Pilih Tipe Kerugian' })}
                              onChange={this.handleSelectChange}
                              value={selectedOption}
                            >
                              <Option value=' '><IntlMessages id='Pilih Tipe Kerugian' /></Option>
                              <Option value='barang'><IntlMessages id='Barang Pribadi' /></Option>
                              <Option value='kendaraan'><IntlMessages id='Kendaraan Pribadi' /></Option>
                              <Option value='lainnya'><IntlMessages id='Lainnya' /></Option>
                            </Select>
                          )}
                        </FormItem>
                      </Col>
                    </Row>
                  </FormItem>
                  <FormItem>
                    <Row gutter={8}>
                      <Col span={24}>
                        <FormItem>
                          <Checkbox
                            checked={this.state.termsValue}
                            onChange={this.onTermsChange}
                            style={{ fontSize: '11px' }}
                          >
                            <IntlMessages id='Saya telah membaca, memahami dan menyetujui' />{' '}
                            <a onClick={this.openTermsContent}><IntlMessages id='Syarat dan Ketentuan yang berlaku' /></a>
                          </Checkbox>
                        </FormItem>
                      </Col>
                    </Row>
                  </FormItem>
                  <FormItem>
                    <Row gutter={8}>
                      <Col span={24}>
                        <FormItem>
                          <Button
                            type='primary'
                            htmlType='submit'
                            style={{ width: '100%' }}
                            disabled={this.state.loading || checkOrderId || checkEmail || checkName || optionSelected}
                          >
                            <IntlMessages id='Kirim Klaim' />
                          </Button>
                        </FormItem>
                      </Col>
                    </Row>
                  </FormItem>
                </Form>
              </Card>
            </Col>
          </Row>
        </GolifeStyled>
      </div>
    )
  }
}

const mapStateToProps = state => {
  return {
    ...state,
    GolifePassenger: state.GolifePassenger,
    dataUser: state.Auth.profile,
    dataBenefits: state.GolifePassenger.benefits,
    dataClaim: state.GolifePassenger.claim,
    createClaimGocarPassengerStatus: state.GolifePassenger.createClaimGocarPassengerStatus
  }
}

export default connect(mapStateToProps, {
  resetStateGolifePassenger,
  getProfileDetails,
  createOrder,
  getBenefits,
  ...updateUser
})(Form.create()(injectIntl(GolifePassenger)))
